 "errores": [
  {
   "regla": "POP R2",
   "mensaje": "no usa TDIndex() para iterar los puntos",
   "fix": "const uint id = TDIndex();"
  },
  {
   "regla": "POP R2",
   "mensaje": "falta la guarda de rango",
   "fix": "if (id >= TDNumElements()) return;"
  },
  {
   "regla": "POP R4 (y R1 si es P)",
   "mensaje": "'P' se escribe y se lee en el mismo main()",
   "fix": "si es la salida [P] usá TDIn_P(0, id); si necesitás leerla, poné outputaccess='readwrite'"
  }
 ],
 "warnings": [
  {
   "regla": "POP R1",
   "mensaje": "escribe P sin leer la entrada (TDIn_P): verificá el origen de los valores",
   "fix": "P[id] = TDIn_P(0, id) * ...;"
  }
 ],
 "notas": [
  {
   "regla": "POP R3",
   "mensaje": "los atributos que se escriben y no vienen en la entrada hay que crearlos en la página Create Attributes (outputattrs solo selecciona atributos existentes)"
  },
  {
   "attr": "Cd",
   "parametros": {
    "attr0name": "Custom",
    "attr0customname": "Cd",
    "attr0numcomps": 4
   }
  }
 ]
